usage.rust:
use crate::parts::byte_entropy::{entropy, windows};

// Whole buffer, in bits per byte: same f64 as
// scipy.stats.entropy(numpy.bincount(data, minlength=256), base=2)
let h = entropy(&binary);

// Every whole 4 KiB window (step 4 KiB); a partial window at the end is skipped
for w in windows(&binary, 4096, 4096)? {
    if w.entropy > 7.2 {
        println!("offset {:#x}: likely packed ({:.2} bits/byte)", w.offset, w.entropy);
    }
}
